"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["68191"],{32136(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.valores_categoricos_insuficientes","status":422,"titulo":"Tipo de conceito categ\xf3rico exige ao menos dois valores"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.valores_categoricos_insuficientes","requisitos":[],"oQueAconteceu":["O tipo de conceito \xe9 de natureza `categorico`, mas `valores` est\xe1 ausente, nulo, vazio ou com um \xfanico item. Escolher entre valores s\xf3 faz sentido com pelo menos duas op\xe7\xf5es. A cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) e a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) conferem a mesma regra, e a lista enviada substitui por inteiro a que o tipo tinha.","A recusa vem na lista `errors` da resposta, com `field` igual a `valores`. As demais recusas do conte\xfado, inclusive as dos itens enviados, v\xeam na mesma resposta, e nada \xe9 gravado.","Todo item de `valores` precisa dizer se conta como aprova\xe7\xe3o: o item que omite `contaComoAprovacao` \xe9 recusado no pr\xf3prio campo, com [conta como aprova\xe7\xe3o obrigat\xf3ria](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_conta_como_aprovacao_obrigatoria). Um \xfanico objeto `{}` em `valores` produz as recusas de c\xf3digo, de r\xf3tulo e de aprova\xe7\xe3o do item, al\xe9m desta, porque a lista continua com menos de dois valores.","Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Envie ao menos dois valores, cada um com `codigo`, `rotulo` e `contaComoAprovacao` (este \xfaltimo \xe9 obrigat\xf3rio, mesmo quando falso), por exemplo `[{ \\"codigo\\": \\"APTO\\", \\"rotulo\\": \\"Apto\\", \\"contaComoAprovacao\\": true }, { \\"codigo\\": \\"INAPTO\\", \\"rotulo\\": \\"Inapto\\", \\"contaComoAprovacao\\": false }]`, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);